import * as React from "react";

export const PDF_RENDERED_PAGE_CACHE_MAX_ENTRIES = 6;
export const PDF_RENDERED_PAGE_CACHE_MAX_PIXELS = 24_000_000;

export type PdfRenderedPageSignature = {
  pageNumber: number;
  scale: number;
  rotation: number;
  devicePixelRatio: number;
  viewportWidth: number;
  viewportHeight: number;
};

export type PdfRenderedPageCache = {
  clock: number;
  entries: Map<string, PdfRenderedPageCacheEntry>;
  resetKey: unknown;
};

export type PdfRenderedPageCacheEntry = PdfRenderedPageSignature & {
  canvas: HTMLCanvasElement;
  lastUsed: number;
  pixels: number;
};

export function usePdfRenderedPageCache(resetKey: unknown) {
  const cacheRef = React.useRef<PdfRenderedPageCache>({
    clock: 0,
    entries: new Map(),
    resetKey,
  });
  if (!Object.is(cacheRef.current.resetKey, resetKey)) {
    clearPdfRenderedPageCache(cacheRef.current);
    cacheRef.current.resetKey = resetKey;
  }

  React.useEffect(() => {
    const cache = cacheRef.current;
    if (!Object.is(cache.resetKey, resetKey)) {
      clearPdfRenderedPageCache(cache);
      cache.resetKey = resetKey;
    }
  }, [resetKey]);

  React.useEffect(() => () => clearPdfRenderedPageCache(cacheRef.current), []);

  return cacheRef.current;
}

export function readPdfRenderedPageCache(
  cache: PdfRenderedPageCache | undefined,
  requested: PdfRenderedPageSignature,
) {
  if (!cache) return null;

  let bestEntry: PdfRenderedPageCacheEntry | null = null;
  for (const entry of cache.entries.values()) {
    if (!doesRenderedPageSatisfyRequest(entry, requested)) continue;
    if (
      !bestEntry ||
      entry.devicePixelRatio < bestEntry.devicePixelRatio ||
      (entry.devicePixelRatio === bestEntry.devicePixelRatio &&
        entry.lastUsed > bestEntry.lastUsed)
    ) {
      bestEntry = entry;
    }
  }

  if (!bestEntry) return null;
  cache.clock += 1;
  bestEntry.lastUsed = cache.clock;
  return bestEntry;
}

export function writePdfRenderedPageCache({
  cache,
  rendered,
  sourceCanvas,
}: {
  cache: PdfRenderedPageCache | undefined;
  rendered: PdfRenderedPageSignature;
  sourceCanvas: HTMLCanvasElement;
}) {
  if (!cache || sourceCanvas.width <= 0 || sourceCanvas.height <= 0) return;

  const canvas = document.createElement("canvas");
  canvas.width = sourceCanvas.width;
  canvas.height = sourceCanvas.height;
  const context = canvas.getContext("2d");
  if (!context || typeof context.drawImage !== "function") return;

  context.drawImage(sourceCanvas, 0, 0);
  cache.clock += 1;
  const key = getPdfRenderedPageCacheKey(rendered);
  cache.entries.set(key, {
    ...rendered,
    canvas,
    lastUsed: cache.clock,
    pixels: canvas.width * canvas.height,
  });
  evictPdfRenderedPageCache(cache, key);
}

export function clearPdfRenderedPageCache(cache: PdfRenderedPageCache) {
  cache.clock = 0;
  cache.entries.clear();
}

function evictPdfRenderedPageCache(
  cache: PdfRenderedPageCache,
  retainedKey: string,
) {
  let totalPixels = getTotalCachedPixels(cache);

  while (
    cache.entries.size > PDF_RENDERED_PAGE_CACHE_MAX_ENTRIES ||
    totalPixels > PDF_RENDERED_PAGE_CACHE_MAX_PIXELS
  ) {
    const evicted = findPdfRenderedPageCacheEviction(cache, retainedKey);
    if (!evicted) return;

    totalPixels -= evicted.entry.pixels;
    cache.entries.delete(evicted.key);
  }
}

function findPdfRenderedPageCacheEviction(
  cache: PdfRenderedPageCache,
  retainedKey: string,
) {
  let oldest: { key: string; entry: PdfRenderedPageCacheEntry } | null = null;

  for (const [key, entry] of cache.entries) {
    if (key === retainedKey) continue;
    if (!oldest || entry.lastUsed < oldest.entry.lastUsed) {
      oldest = { key, entry };
    }
  }

  return oldest;
}

function getTotalCachedPixels(cache: PdfRenderedPageCache) {
  let pixels = 0;
  for (const entry of cache.entries.values()) {
    pixels += entry.pixels;
  }
  return pixels;
}

function doesRenderedPageSatisfyRequest(
  rendered: PdfRenderedPageSignature,
  requested: PdfRenderedPageSignature,
) {
  return (
    rendered.pageNumber === requested.pageNumber &&
    rendered.scale === requested.scale &&
    rendered.rotation === requested.rotation &&
    rendered.viewportWidth === requested.viewportWidth &&
    rendered.viewportHeight === requested.viewportHeight &&
    rendered.devicePixelRatio >= requested.devicePixelRatio
  );
}

function getPdfRenderedPageCacheKey(rendered: PdfRenderedPageSignature) {
  return [
    rendered.pageNumber,
    rendered.scale,
    rendered.rotation,
    rendered.devicePixelRatio,
    rendered.viewportWidth,
    rendered.viewportHeight,
  ].join(":");
}

"use client";

/* eslint-disable no-restricted-syntax -- TODO(no-useEffect): existing direct React effect usage; migrate to useMountEffect or a Rule 1-5 replacement. */

import * as React from "react";

import { getPdfPageResource } from "@/lib/pdf-document-resource";
import type { PdfDocumentProxy } from "@/lib/pdf-document-types";

export const PDF_PAGE_METRIC_CONCURRENCY = 4;

export type PdfPageMetric = {
  pageNumber: number;
  width: number;
  height: number;
  rotation: number;
};

export type PdfPageMetrics = {
  metricByPageNumber: ReadonlyMap<number, PdfPageMetric>;
  requestPageMetrics: (pageNumbers: Iterable<number>) => void;
  status: "idle" | "loading";
};

type MetricControllerState = {
  documentKey: unknown;
  pageCount: number;
  metricByPageNumber: ReadonlyMap<number, PdfPageMetric>;
  queuedPageNumbers: readonly number[];
  loadingPageNumbers: ReadonlySet<number>;
  error: unknown;
};

type MetricAction =
  | { type: "reset"; documentKey: unknown; pageCount: number }
  | {
      type: "enqueue";
      documentKey: unknown;
      pageCount: number;
      pageNumbers: readonly number[];
    }
  | { type: "start"; documentKey: unknown; pageNumbers: readonly number[] }
  | { type: "resolve"; documentKey: unknown; metric: PdfPageMetric }
  | { type: "reject"; documentKey: unknown; error: unknown };

export function usePdfPageMetrics(
  document: PdfDocumentProxy,
  resetKey: unknown,
): PdfPageMetrics {
  const workerSequenceRef = React.useRef(0);
  const [state, dispatch] = React.useReducer(
    metricControllerReducer,
    undefined,
    () => createMetricControllerState(resetKey, document.numPages),
  );
  const visibleState = Object.is(state.documentKey, resetKey)
    ? state
    : createMetricControllerState(resetKey, document.numPages);
  const status =
    visibleState.queuedPageNumbers.length > 0 ||
    visibleState.loadingPageNumbers.size > 0
      ? "loading"
      : "idle";

  React.useEffect(() => {
    workerSequenceRef.current += 1;
    dispatch({
      type: "reset",
      documentKey: resetKey,
      pageCount: document.numPages,
    });
  }, [document, resetKey]);

  const requestPageMetrics = React.useCallback(
    (pageNumbers: Iterable<number>) => {
      const requestedPageNumbers = Array.from(pageNumbers)
        .map((pageNumber) =>
          normalizePdfPageNumber(pageNumber, document.numPages),
        )
        .filter((pageNumber): pageNumber is number => pageNumber != null);

      if (requestedPageNumbers.length === 0) return;

      dispatch({
        type: "enqueue",
        documentKey: resetKey,
        pageCount: document.numPages,
        pageNumbers: requestedPageNumbers,
      });
    },
    [document.numPages, resetKey],
  );

  React.useEffect(() => {
    if (!Object.is(state.documentKey, resetKey)) return;
    if (state.error) return;

    const availableSlotCount =
      PDF_PAGE_METRIC_CONCURRENCY - state.loadingPageNumbers.size;
    if (availableSlotCount <= 0) return;

    const startingPageNumbers = state.queuedPageNumbers.slice(
      0,
      availableSlotCount,
    );
    if (startingPageNumbers.length === 0) return;

    const sequence = workerSequenceRef.current;
    dispatch({
      type: "start",
      documentKey: resetKey,
      pageNumbers: startingPageNumbers,
    });

    for (const pageNumber of startingPageNumbers) {
      void getPdfPageResource(document, pageNumber, {
        retainRejected: true,
      })
        .then((page) => {
          if (workerSequenceRef.current !== sequence) return;

          const rotation = page.rotate ?? 0;
          const viewport = page.getViewport({ scale: 1, rotation });
          dispatch({
            type: "resolve",
            documentKey: resetKey,
            metric: {
              pageNumber,
              width: viewport.width,
              height: viewport.height,
              rotation,
            },
          });
        })
        .catch((error: unknown) => {
          if (workerSequenceRef.current !== sequence) return;
          dispatch({ type: "reject", documentKey: resetKey, error });
        });
    }
  }, [
    document,
    resetKey,
    state.documentKey,
    state.error,
    state.loadingPageNumbers,
    state.queuedPageNumbers,
  ]);

  if (visibleState.error) throw visibleState.error;

  return {
    metricByPageNumber: visibleState.metricByPageNumber,
    requestPageMetrics,
    status,
  };
}

function metricControllerReducer(
  state: MetricControllerState,
  action: MetricAction,
): MetricControllerState {
  switch (action.type) {
    case "reset":
      return createMetricControllerState(action.documentKey, action.pageCount);
    case "enqueue":
      return enqueuePageMetrics(state, action);
    case "start":
      return startPageMetrics(state, action);
    case "resolve":
      return resolvePageMetric(state, action);
    case "reject":
      if (!Object.is(state.documentKey, action.documentKey)) return state;
      return {
        ...state,
        queuedPageNumbers: [],
        loadingPageNumbers: new Set(),
        error: action.error,
      };
  }
}

function createMetricControllerState(
  documentKey: unknown,
  pageCount: number,
): MetricControllerState {
  return {
    documentKey,
    pageCount,
    metricByPageNumber: new Map(),
    queuedPageNumbers: [],
    loadingPageNumbers: new Set(),
    error: null,
  };
}

function enqueuePageMetrics(
  state: MetricControllerState,
  action: Extract<MetricAction, { type: "enqueue" }>,
): MetricControllerState {
  const baseState = Object.is(state.documentKey, action.documentKey)
    ? state
    : createMetricControllerState(action.documentKey, action.pageCount);
  const queuedPageNumberSet = new Set(baseState.queuedPageNumbers);
  const queuedPageNumbers = [...baseState.queuedPageNumbers];

  for (const pageNumber of action.pageNumbers) {
    if (baseState.metricByPageNumber.has(pageNumber)) continue;
    if (baseState.loadingPageNumbers.has(pageNumber)) continue;
    if (queuedPageNumberSet.has(pageNumber)) continue;

    queuedPageNumberSet.add(pageNumber);
    queuedPageNumbers.push(pageNumber);
  }

  if (queuedPageNumbers.length === baseState.queuedPageNumbers.length) {
    return baseState;
  }

  return {
    ...baseState,
    queuedPageNumbers,
  };
}

function startPageMetrics(
  state: MetricControllerState,
  action: Extract<MetricAction, { type: "start" }>,
): MetricControllerState {
  if (!Object.is(state.documentKey, action.documentKey)) return state;

  const startingPageNumberSet = new Set(action.pageNumbers);
  const queuedPageNumbers = state.queuedPageNumbers.filter(
    (pageNumber) => !startingPageNumberSet.has(pageNumber),
  );
  const loadingPageNumbers = new Set(state.loadingPageNumbers);

  for (const pageNumber of action.pageNumbers) {
    if (state.metricByPageNumber.has(pageNumber)) continue;
    loadingPageNumbers.add(pageNumber);
  }

  return {
    ...state,
    queuedPageNumbers,
    loadingPageNumbers,
  };
}

function resolvePageMetric(
  state: MetricControllerState,
  action: Extract<MetricAction, { type: "resolve" }>,
): MetricControllerState {
  if (!Object.is(state.documentKey, action.documentKey)) return state;

  const loadingPageNumbers = new Set(state.loadingPageNumbers);
  loadingPageNumbers.delete(action.metric.pageNumber);

  const metricByPageNumber = new Map(state.metricByPageNumber);
  metricByPageNumber.set(action.metric.pageNumber, action.metric);

  return {
    ...state,
    metricByPageNumber,
    loadingPageNumbers,
  };
}

function normalizePdfPageNumber(pageNumber: number, pageCount: number) {
  return Number.isInteger(pageNumber) &&
    pageNumber >= 1 &&
    pageNumber <= pageCount
    ? pageNumber
    : null;
}

"use client";

import * as React from "react";

import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource";
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source";

import { useOptionalFileViewerResource } from "./file-viewer-internal";
import {
  PdfResourceContent,
  type PdfViewerContentProps,
} from "./pdf-viewer-content";
import type { PdfViewerHandle } from "./pdf-viewer-types";

export type PdfDocumentSource = UrlViewerSource | BlobViewerSource;

export type PdfViewerThumbnailsState = {
  currentPage: number | null;
  onSelectPage: ((page: number) => void) | undefined;
  resource: ViewerResource;
};

export interface PdfViewerProviderProps {
  source?: PdfDocumentSource;
  children: React.ReactNode;
}

type PdfViewerContextValue = {
  currentPage: number | null;
  resource: ViewerResource;
  setCurrentPage: (page: number | null) => void;
  setViewerHandle: (handle: PdfViewerHandle | null) => void;
  viewerHandle: PdfViewerHandle | null;
};

type PdfDocumentPagesState = {
  resource: ViewerResource;
  setCurrentPage: (page: number | null) => void;
  setViewerHandle: (handle: PdfViewerHandle | null) => void;
};

const PdfViewerContext = React.createContext<PdfViewerContextValue | null>(
  null,
);

function usePdfViewerContext(
  consumer = "PdfViewer parts",
): PdfViewerContextValue {
  const context = React.useContext(PdfViewerContext);
  if (!context) {
    throw new Error(`${consumer} must be used within PdfViewerProvider.`);
  }
  return context;
}

export function usePdfViewerThumbnails(): PdfViewerThumbnailsState {
  const { currentPage, resource, viewerHandle } = usePdfViewerContext(
    "usePdfViewerThumbnails",
  );
  const onSelectPage = React.useCallback(
    (page: number) => viewerHandle?.scrollToPage(page),
    [viewerHandle],
  );

  return {
    currentPage,
    onSelectPage: viewerHandle ? onSelectPage : undefined,
    resource,
  };
}

function usePdfDocumentPagesState(): PdfDocumentPagesState {
  const { resource, setCurrentPage, setViewerHandle } = usePdfViewerContext();
  return { resource, setCurrentPage, setViewerHandle };
}

export const PdfViewerPages = React.forwardRef<
  PdfViewerHandle,
  PdfViewerContentProps
>(function PdfViewerPages(props, ref) {
  const { resource, setCurrentPage, setViewerHandle } =
    usePdfDocumentPagesState();
  const { onVisiblePageChange } = props;
  const handleVisiblePageChange = React.useCallback(
    (page: number) => {
      setCurrentPage(page);
      onVisiblePageChange?.(page);
    },
    [onVisiblePageChange, setCurrentPage],
  );
  const handleRef = React.useCallback(
    (handle: PdfViewerHandle | null) => {
      setViewerHandle(handle);
      if (typeof ref === "function") {
        ref(handle);
        return;
      }
      if (ref) ref.current = handle;
    },
    [ref, setViewerHandle],
  );

  return (
    <PdfResourceContent
      {...props}
      ref={handleRef}
      resource={resource}
      controls={false}
      onVisiblePageChange={handleVisiblePageChange}
    />
  );
});

export function PdfViewerProvider({
  source,
  children,
}: PdfViewerProviderProps) {
  const fileViewerResource = useOptionalFileViewerResource();
  const resource = React.useMemo(() => {
    if (source) return createViewerResource(source);
    if (fileViewerResource) return fileViewerResource;
    throw new Error(
      "PdfViewerProvider requires a source or enclosing FileViewer.",
    );
  }, [fileViewerResource, source]);
  const [currentPage, setCurrentPage] = React.useState<number | null>(null);
  const [viewerHandle, setViewerHandle] =
    React.useState<PdfViewerHandle | null>(null);
  const value = React.useMemo<PdfViewerContextValue>(
    () => ({
      currentPage,
      resource,
      setCurrentPage,
      setViewerHandle,
      viewerHandle,
    }),
    [currentPage, resource, viewerHandle],
  );

  return (
    <PdfViewerContext.Provider value={value}>
      {children}
    </PdfViewerContext.Provider>
  );
}

"use client";

/* eslint-disable no-restricted-syntax -- TODO(no-useEffect): existing direct React effect usage; migrate to useMountEffect or a Rule 1-5 replacement. */

import * as React from "react";
import { PanelLeft, PanelRight } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";

// Stock Button no longer exports ButtonProps or a `loading` prop. ViewerSidebarTrigger
// keeps its own `loading` API, so we define ButtonProps locally as the stock Button's
// props plus the retab `loading` flag (translated to disabled + Spinner at the leaf).
type ButtonProps = React.ComponentProps<typeof Button> & {
  loading?: boolean;
};

export type ViewerRootProps = React.ComponentProps<"div"> & {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  mode?: ViewerSidebarRequestedMode;
  inlineBreakpoint?: number;
  sidebarSide?: ViewerSidebarSide;
  sidebarCollapsible?: ViewerSidebarCollapsible;
};

export type ViewerSidebarMode = "inline" | "overlay";
export type ViewerSidebarRequestedMode = "auto" | ViewerSidebarMode;
export type ViewerSidebarState = "expanded" | "collapsed";
export type ViewerSidebarContextValue = {
  state: ViewerSidebarState;
  open: boolean;
  setOpen: (value: boolean | ((open: boolean) => boolean)) => void;
  toggleSidebar: () => void;
  canToggleSidebar: boolean;
  mode: ViewerSidebarMode;
};
export type ViewerFrameProps = React.ComponentProps<"div">;

type ViewerSidebarSide = "left" | "right";
type ViewerSidebarCollapsible = "offcanvas" | "none";
type ViewerSidebarRegistration = {
  collapsible: ViewerSidebarCollapsible;
  element: HTMLElement;
  id: string;
  instanceId: string;
  side: ViewerSidebarSide;
  width: string;
};

type ViewerSidebarRegistrationContextValue = {
  defaultSidebarCollapsible: ViewerSidebarCollapsible;
  defaultSidebarSide: ViewerSidebarSide;
  hasSidebar: boolean;
  sidebarState: ViewerSidebarContextValue;
  registerSidebar: (registration: ViewerSidebarRegistration) => () => void;
  rootId: string;
  sidebarId: string;
  sidebarSide: ViewerSidebarSide;
  setLastTriggerElement: (element: HTMLElement | null) => void;
};

const VIEWER_SIDEBAR_INLINE_BREAKPOINT = 768;
const VIEWER_SIDEBAR_MODE_HYSTERESIS = 16;
const VIEWER_SIDEBAR_WIDTH = "10rem";

const ViewerSidebarStateContext =
  React.createContext<ViewerSidebarContextValue | null>(null);
const ViewerSidebarRegistrationContext =
  React.createContext<ViewerSidebarRegistrationContextValue | null>(null);

function resolveSidebarMode({
  requestedMode,
  width,
  inlineBreakpoint,
}: {
  requestedMode: ViewerSidebarRequestedMode;
  width: number | null;
  inlineBreakpoint: number;
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode;
  if (width === null) return "overlay";
  return width >= inlineBreakpoint ? "inline" : "overlay";
}

function resolveMeasuredSidebarMode({
  currentMode,
  hasMeasured,
  inlineBreakpoint,
  requestedMode,
  width,
}: {
  currentMode: ViewerSidebarMode;
  hasMeasured: boolean;
  inlineBreakpoint: number;
  requestedMode: ViewerSidebarRequestedMode;
  width: number;
}): ViewerSidebarMode {
  if (requestedMode !== "auto") return requestedMode;
  if (!hasMeasured) {
    return width >= inlineBreakpoint ? "inline" : "overlay";
  }

  if (currentMode === "inline") {
    return width < inlineBreakpoint - VIEWER_SIDEBAR_MODE_HYSTERESIS
      ? "overlay"
      : "inline";
  }

  return width > inlineBreakpoint + VIEWER_SIDEBAR_MODE_HYSTERESIS
    ? "inline"
    : "overlay";
}

const useIsoLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect;

function isAriaDisabled(value: unknown): boolean {
  return value === true || value === "true";
}

export function useViewerSidebar(): ViewerSidebarContextValue {
  const context = React.useContext(ViewerSidebarStateContext);
  if (!context) {
    throw new Error("useViewerSidebar must be used within a ViewerRoot.");
  }
  return context;
}

export function useOptionalViewerSidebar(): ViewerSidebarContextValue | null {
  return React.useContext(ViewerSidebarStateContext);
}

function useViewerSidebarRegistrationContext(
  consumer: string,
): ViewerSidebarRegistrationContextValue {
  const context = React.useContext(ViewerSidebarRegistrationContext);
  if (!context) {
    throw new Error(`${consumer} must be used within a ViewerRoot.`);
  }
  return context;
}

export function ViewerRoot({
  className,
  style,
  defaultOpen = false,
  open: openProp,
  onOpenChange,
  mode = "auto",
  inlineBreakpoint = VIEWER_SIDEBAR_INLINE_BREAKPOINT,
  sidebarSide = "left",
  sidebarCollapsible = "offcanvas",
  ...props
}: ViewerRootProps) {
  const rootRef = React.useRef<HTMLDivElement | null>(null);
  const reactId = React.useId();
  const rootId = `${reactId}-viewer-root`;
  const fallbackSidebarId = `${reactId}-viewer-sidebar`;
  const isControlled = openProp !== undefined;
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
  const open = openProp ?? internalOpen;
  const openRef = React.useRef(open);
  const hasMeasuredSidebarWidthRef = React.useRef(false);
  const lastTriggerElementRef = React.useRef<HTMLElement | null>(null);
  const registeredSidebarRef = React.useRef<ViewerSidebarRegistration | null>(
    null,
  );
  const [registeredSidebar, setRegisteredSidebar] =
    React.useState<ViewerSidebarRegistration | null>(null);
  const [resolvedSidebarMode, setResolvedSidebarMode] =
    React.useState<ViewerSidebarMode>(() =>
      resolveSidebarMode({
        requestedMode: mode,
        width: null,
        inlineBreakpoint,
      }),
    );

  React.useEffect(() => {
    openRef.current = open;
  }, [open]);

  React.useEffect(() => {
    if (mode === "auto") return;
    setResolvedSidebarMode((currentMode) => {
      const nextMode = mode;
      return currentMode === nextMode ? currentMode : nextMode;
    });
  }, [mode]);

  useIsoLayoutEffect(() => {
    const element = rootRef.current;
    const ResizeObserverConstructor = globalThis.ResizeObserver;
    if (!element || typeof ResizeObserverConstructor === "undefined") return;
    if (mode !== "auto") {
      setResolvedSidebarMode(mode);
      return;
    }

    const updateMode = () => {
      const nextWidth = element.getBoundingClientRect().width;
      if (nextWidth === 0) return;

      setResolvedSidebarMode((currentMode) => {
        const nextMode = resolveMeasuredSidebarMode({
          currentMode,
          hasMeasured: hasMeasuredSidebarWidthRef.current,
          requestedMode: mode,
          width: nextWidth,
          inlineBreakpoint,
        });

        hasMeasuredSidebarWidthRef.current = true;
        return currentMode === nextMode ? currentMode : nextMode;
      });
    };

    updateMode();

    const observer = new ResizeObserverConstructor(updateMode);
    observer.observe(element);

    return () => observer.disconnect();
  }, [inlineBreakpoint, mode]);

  const setOpen = React.useCallback(
    (value: boolean | ((open: boolean) => boolean)) => {
      const previousOpen = isControlled ? open : openRef.current;
      const nextOpen =
        typeof value === "function" ? value(previousOpen) : value;

      if (nextOpen === previousOpen) {
        return;
      }

      if (!isControlled) {
        openRef.current = nextOpen;
        setInternalOpen(nextOpen);
      }
      onOpenChange?.(nextOpen);
    },
    [isControlled, onOpenChange, open],
  );

  const registerSidebar = React.useCallback(
    (registration: ViewerSidebarRegistration) => {
      const currentRegistration = registeredSidebarRef.current;

      if (
        currentRegistration &&
        currentRegistration.instanceId !== registration.instanceId
      ) {
        throw new Error(
          "ViewerRoot supports one primary ViewerSidebar. Use a nested ViewerRoot for a complete nested viewer, or put secondary content inside ViewerSurface.",
        );
      }

      registeredSidebarRef.current = registration;
      setRegisteredSidebar(registration);

      return () => {
        if (
          registeredSidebarRef.current?.instanceId !== registration.instanceId
        ) {
          return;
        }

        registeredSidebarRef.current = null;
        setRegisteredSidebar(null);
      };
    },
    [],
  );

  const toggleSidebar = React.useCallback(() => {
    setOpen((currentOpen) => !currentOpen);
  }, [setOpen]);

  const hasSidebar = registeredSidebar !== null;
  const effectiveOpen = registeredSidebar?.collapsible === "none" ? true : open;
  const state: ViewerSidebarState = effectiveOpen ? "expanded" : "collapsed";
  const canToggleSidebar =
    hasSidebar && registeredSidebar.collapsible !== "none";
  const sidebarId = registeredSidebar?.id ?? fallbackSidebarId;
  const resolvedSidebarSide = registeredSidebar?.side ?? sidebarSide;
  const sidebarWidth = registeredSidebar?.width ?? VIEWER_SIDEBAR_WIDTH;
  const setLastTriggerElement = React.useCallback(
    (element: HTMLElement | null) => {
      lastTriggerElementRef.current = element;
    },
    [],
  );

  React.useEffect(() => {
    if (
      !open ||
      !canToggleSidebar ||
      resolvedSidebarMode !== "overlay" ||
      typeof document === "undefined"
    ) {
      return;
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
        const triggerElement =
          lastTriggerElementRef.current?.isConnected === true
            ? lastTriggerElementRef.current
            : rootRef.current?.querySelector<HTMLElement>(
                "[data-viewer-sidebar-trigger]",
              );
        triggerElement?.focus();
      }
    };
    const handlePointerDown = (event: PointerEvent) => {
      const target = event.target;

      if (
        target instanceof Node &&
        registeredSidebar?.element.contains(target)
      ) {
        return;
      }

      if (target instanceof Element) {
        const triggerElement = target.closest<HTMLElement>(
          "[data-viewer-sidebar-trigger]",
        );
        if (triggerElement?.dataset.viewerRootId === rootId) {
          return;
        }
      }

      setOpen(false);
    };

    document.addEventListener("keydown", handleKeyDown);
    document.addEventListener("pointerdown", handlePointerDown);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.removeEventListener("pointerdown", handlePointerDown);
    };
  }, [
    canToggleSidebar,
    open,
    registeredSidebar,
    resolvedSidebarMode,
    rootId,
    setOpen,
  ]);

  const sidebarStateContext = React.useMemo<ViewerSidebarContextValue>(
    () => ({
      state,
      open: effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      mode: resolvedSidebarMode,
    }),
    [
      state,
      effectiveOpen,
      setOpen,
      toggleSidebar,
      canToggleSidebar,
      resolvedSidebarMode,
    ],
  );

  const sidebarRegistrationContext =
    React.useMemo<ViewerSidebarRegistrationContextValue>(
      () => ({
        defaultSidebarCollapsible: sidebarCollapsible,
        defaultSidebarSide: sidebarSide,
        hasSidebar,
        sidebarState: sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarId,
        sidebarSide: resolvedSidebarSide,
        setLastTriggerElement,
      }),
      [
        hasSidebar,
        sidebarCollapsible,
        resolvedSidebarSide,
        sidebarStateContext,
        registerSidebar,
        rootId,
        sidebarId,
        sidebarSide,
        setLastTriggerElement,
      ],
    );

  return (
    <ViewerSidebarStateContext.Provider value={sidebarStateContext}>
      <ViewerSidebarRegistrationContext.Provider
        value={sidebarRegistrationContext}
      >
        <div
          ref={rootRef}
          data-slot="viewer-root"
          data-viewer-root-id={rootId}
          className={cn(
            "relative flex min-h-0 flex-col overflow-hidden",
            className,
          )}
          style={
            {
              ...style,
              "--viewer-sidebar-width": sidebarWidth,
            } as React.CSSProperties
          }
          {...props}
        />
      </ViewerSidebarRegistrationContext.Provider>
    </ViewerSidebarStateContext.Provider>
  );
}

