import * as React from "react";

import { clearPdfDocumentResource } from "@/lib/pdf-document-resource";
import { cn } from "@/lib/utils";
import type { ViewerResource } from "@/lib/viewer-resource";
import { Spinner } from "@/components/ui/spinner";

import {
  buildPdfThumbnailLayout,
  PDF_THUMBNAIL_INITIAL_VIEWPORT_HEIGHT,
  PDF_THUMBNAIL_OVERSCAN,
  type PdfThumbnailShape,
} from "./pdf-thumbnail-layout";
import { PdfThumbnailRailViewport } from "./pdf-thumbnail-rail";
import { usePdfViewerThumbnails } from "./pdf-viewer-context";
import { useIsClient } from "./use-is-client";
import { usePdfThumbnailDocument } from "./use-pdf-thumbnail-document";
import { usePdfThumbnailPageMetrics } from "./use-pdf-thumbnail-page-metrics";
import { usePdfThumbnailWindow } from "./use-pdf-thumbnail-window";
import { useThumbnailRailFollow } from "./use-thumbnail-rail-follow";
import { ViewerErrorBoundary } from "./viewer-error";

export interface PdfViewerThumbnailsProps {
  /** Thumbnail image width in CSS pixels. The sidebar shell owns rail width. */
  thumbnailWidth?: number;
  /** Preserve page aspect or crop each page preview into a square frame. */
  thumbnailShape?: PdfThumbnailShape;
  className?: string;
}

export interface PdfThumbnailRailProps {
  /** Same resource object passed to PdfResourceContent. */
  resource: ViewerResource;
  /** 1-based current page; its thumbnail is highlighted. */
  currentPage?: number | null;
  /** Click a thumbnail to jump the document to that page. */
  onSelectPage?: (page: number) => void;
  /** Thumbnail image width in CSS pixels. The sidebar shell owns rail width. */
  thumbnailWidth?: number;
  /** Preserve page aspect or crop each page preview into a square frame. */
  thumbnailShape?: PdfThumbnailShape;
  className?: string;
}

export function PdfViewerThumbnails({
  className,
  thumbnailShape,
  thumbnailWidth,
}: PdfViewerThumbnailsProps) {
  const thumbnails = usePdfViewerThumbnails();

  return (
    <PdfThumbnailRail
      className={className}
      currentPage={thumbnails.currentPage}
      onSelectPage={thumbnails.onSelectPage}
      resource={thumbnails.resource}
      thumbnailShape={thumbnailShape}
      thumbnailWidth={thumbnailWidth}
    />
  );
}

export function PdfThumbnailRail({
  className,
  currentPage,
  onSelectPage,
  resource,
  thumbnailShape,
  thumbnailWidth,
}: PdfThumbnailRailProps) {
  const isClient = useIsClient();

  if (!isClient) {
    return <ThumbnailsFallback className={className} />;
  }

  return (
    <ViewerErrorBoundary
      className={cn("h-full", className)}
      download={resource.originalDownload}
      format="pdf"
      onRetry={() => clearPdfDocumentResource(resource.content)}
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
      variant="inline"
    >
      <React.Suspense fallback={<ThumbnailsFallback />}>
        <PdfThumbnailRailInner
          currentPage={currentPage}
          onSelectPage={onSelectPage}
          resource={resource}
          thumbnailShape={thumbnailShape}
          thumbnailWidth={thumbnailWidth}
          className="h-full"
        />
      </React.Suspense>
    </ViewerErrorBoundary>
  );
}

function PdfThumbnailRailInner({
  resource,
  currentPage,
  onSelectPage,
  thumbnailShape = "page",
  thumbnailWidth = 120,
  className,
}: PdfThumbnailRailProps) {
  const doc = usePdfThumbnailDocument(resource);
  const pageMetrics = usePdfThumbnailPageMetrics(doc, doc);
  const { metricByPageNumber, pageCount, requestPageMetrics } = pageMetrics;
  const viewportRef = React.useRef<HTMLDivElement | null>(null);

  const layout = React.useMemo(
    () =>
      buildPdfThumbnailLayout({
        pageCount,
        width: thumbnailWidth,
        shape: thumbnailShape,
        metricByPageNumber,
      }),
    [metricByPageNumber, pageCount, thumbnailShape, thumbnailWidth],
  );
  const thumbnailWindow = usePdfThumbnailWindow({
    layout,
    viewportRef,
    overscan: PDF_THUMBNAIL_OVERSCAN,
    initialViewportHeight: PDF_THUMBNAIL_INITIAL_VIEWPORT_HEIGHT,
  });
  const follow = useThumbnailRailFollow({
    currentPage,
    layout,
    viewportRef,
    resetKey: doc,
  });
  React.useEffect(() => {
    requestPageMetrics(
      getRequestedThumbnailMetricPages({
        currentPage,
        pageCount: layout.pageCount,
        visibleItems: thumbnailWindow.visibleItems,
      }),
    );
  }, [
    currentPage,
    layout.pageCount,
    requestPageMetrics,
    thumbnailWindow.visibleItems,
  ]);

  return (
    <PdfThumbnailRailViewport
      doc={doc}
      layout={layout}
      visibleItems={thumbnailWindow.visibleItems}
      currentPage={currentPage}
      viewportRef={viewportRef}
      onSelectPage={onSelectPage}
      onPageActivate={follow.onPageActivate}
      onPointerEnter={follow.onPointerEnter}
      onPointerLeave={follow.onPointerLeave}
      onScroll={follow.onScroll}
      className={className}
    />
  );
}

function getRequestedThumbnailMetricPages({
  currentPage,
  pageCount,
  visibleItems,
}: {
  currentPage: number | null | undefined;
  pageCount: number;
  visibleItems: readonly { pageNumber: number }[];
}) {
  const pageNumbers = new Set<number>();
  for (const item of visibleItems) pageNumbers.add(item.pageNumber);
  if (
    currentPage != null &&
    Number.isInteger(currentPage) &&
    currentPage >= 1 &&
    currentPage <= pageCount
  ) {
    pageNumbers.add(currentPage);
  }

  return pageNumbers;
}

function ThumbnailsFallback({ className }: { className?: string }) {
  return (
    <div
      className={cn(
        "bg-muted/30 flex h-full items-center justify-center",
        className,
      )}
    >
      <Spinner className="text-muted-foreground size-4" />
    </div>
  );
}

export const PDF_THUMBNAIL_OVERSCAN = 16;
export const PDF_THUMBNAIL_INITIAL_VIEWPORT_HEIGHT = 680;
export const PDF_THUMBNAIL_DEFAULT_ASPECT = 4 / 3;
export const PDF_THUMBNAIL_LABEL_AND_GAP_HEIGHT = 22;

export type PdfThumbnailShape = "page" | "square";

export interface PdfThumbnailPageMetric {
  pageNumber: number;
  width: number;
  height: number;
}

export interface PdfThumbnailLayoutItem {
  pageNumber: number;
  pageIndex: number;
  top: number;
  height: number;
  imageWidth: number;
  imageHeight: number;
}

export interface PdfThumbnailLayout {
  pageCount: number;
  width: number;
  shape: PdfThumbnailShape;
  estimatedImageHeight: number;
  estimatedItemHeight: number;
  labelAndGapHeight: number;
  metricByPageNumber: ReadonlyMap<number, PdfThumbnailPageMetric>;
  prefixHeightDeltas: readonly PdfThumbnailHeightDelta[];
  totalHeight: number;
}

interface PdfThumbnailHeightDelta {
  pageNumber: number;
  prefixDeltaAfterPage: number;
}

export function buildPdfThumbnailLayout({
  pageCount,
  width,
  metricByPageNumber,
  labelAndGapHeight = PDF_THUMBNAIL_LABEL_AND_GAP_HEIGHT,
  shape = "page",
}: {
  pageCount: number;
  width: number;
  metricByPageNumber?: ReadonlyMap<number, PdfThumbnailPageMetric>;
  labelAndGapHeight?: number;
  shape?: PdfThumbnailShape;
}): PdfThumbnailLayout {
  const safePageCount = normalizePageCount(pageCount);
  const safeWidth = normalizeWidth(width);
  const safeLabelAndGapHeight = normalizeSize(labelAndGapHeight, 0);
  const safeMetricByPageNumber = metricByPageNumber ?? new Map();
  const estimatedImageHeight = getThumbnailImageHeight({
    width: safeWidth,
    metric: safeMetricByPageNumber.get(1),
    shape,
  });
  const estimatedItemHeight =
    Math.ceil(estimatedImageHeight) + safeLabelAndGapHeight;
  const prefixHeightDeltas = buildPrefixHeightDeltas({
    pageCount: safePageCount,
    width: safeWidth,
    shape,
    estimatedItemHeight,
    metricByPageNumber: safeMetricByPageNumber,
    labelAndGapHeight: safeLabelAndGapHeight,
  });
  const totalHeight =
    safePageCount * estimatedItemHeight +
    (prefixHeightDeltas.at(-1)?.prefixDeltaAfterPage ?? 0);

  return {
    pageCount: safePageCount,
    width: safeWidth,
    shape,
    estimatedImageHeight,
    estimatedItemHeight,
    labelAndGapHeight: safeLabelAndGapHeight,
    metricByPageNumber: safeMetricByPageNumber,
    prefixHeightDeltas,
    totalHeight,
  };
}

export function getPdfThumbnailLayoutItem(
  layout: PdfThumbnailLayout,
  pageNumber: number,
): PdfThumbnailLayoutItem | null {
  const normalizedPage = normalizeThumbnailPage(pageNumber, layout.pageCount);
  if (normalizedPage == null) return null;

  const metric = layout.metricByPageNumber.get(normalizedPage);
  const imageHeight = getThumbnailImageHeight({
    width: layout.width,
    metric,
    shape: layout.shape,
  });
  const height = Math.ceil(imageHeight) + layout.labelAndGapHeight;

  return {
    pageNumber: normalizedPage,
    pageIndex: normalizedPage - 1,
    top:
      (normalizedPage - 1) * layout.estimatedItemHeight +
      getPrefixHeightDeltaBeforePage(layout, normalizedPage),
    height,
    imageWidth: layout.width,
    imageHeight,
  };
}

export function getVisiblePdfThumbnailItems({
  layout,
  scrollTop,
  viewportHeight,
  overscan,
}: {
  layout: PdfThumbnailLayout;
  scrollTop: number;
  viewportHeight: number;
  overscan: number;
}) {
  if (layout.pageCount === 0) return [];

  const visibleStart = Math.max(0, scrollTop);
  const visibleEnd = Math.max(visibleStart, visibleStart + viewportHeight);
  const firstVisiblePage = findPdfThumbnailPageByOffset(layout, visibleStart);
  const lastVisiblePage = findPdfThumbnailPageByOffset(layout, visibleEnd);
  const startPage = Math.max(1, firstVisiblePage - overscan);
  const endPage = Math.min(layout.pageCount, lastVisiblePage + overscan);
  const items: PdfThumbnailLayoutItem[] = [];

  for (let pageNumber = startPage; pageNumber <= endPage; pageNumber += 1) {
    const item = getPdfThumbnailLayoutItem(layout, pageNumber);
    if (item) items.push(item);
  }

  return items;
}

export function findPdfThumbnailPageByOffset(
  layout: PdfThumbnailLayout,
  offset: number,
) {
  const safeOffset = Math.max(0, offset);
  let low = 1;
  let high = layout.pageCount;
  let result = 1;

  while (low <= high) {
    const pageNumber = Math.floor((low + high) / 2);
    const item = getPdfThumbnailLayoutItem(layout, pageNumber);
    if (!item) break;

    if (item.top + item.height >= safeOffset) {
      result = pageNumber;
      high = pageNumber - 1;
    } else {
      low = pageNumber + 1;
    }
  }

  return result;
}

export function normalizeThumbnailPage(
  page: number | null | undefined,
  pageCount: number,
): number | null {
  return page != null &&
    Number.isInteger(page) &&
    page >= 1 &&
    page <= pageCount
    ? page
    : null;
}

function getThumbnailImageHeight({
  width,
  metric,
  shape,
}: {
  width: number;
  metric: PdfThumbnailPageMetric | undefined;
  shape: PdfThumbnailShape;
}) {
  if (shape === "square") return width;

  if (
    metric &&
    Number.isFinite(metric.width) &&
    Number.isFinite(metric.height) &&
    metric.width > 0 &&
    metric.height > 0
  ) {
    return width * (metric.height / metric.width);
  }

  return width * PDF_THUMBNAIL_DEFAULT_ASPECT;
}

function buildPrefixHeightDeltas({
  pageCount,
  width,
  shape,
  estimatedItemHeight,
  metricByPageNumber,
  labelAndGapHeight,
}: {
  pageCount: number;
  width: number;
  shape: PdfThumbnailShape;
  estimatedItemHeight: number;
  metricByPageNumber: ReadonlyMap<number, PdfThumbnailPageMetric>;
  labelAndGapHeight: number;
}) {
  let prefixDeltaAfterPage = 0;
  const prefixHeightDeltas: PdfThumbnailHeightDelta[] = [];

  for (const [pageNumber, metric] of [...metricByPageNumber.entries()].sort(
    ([left], [right]) => left - right,
  )) {
    if (normalizeThumbnailPage(pageNumber, pageCount) == null) continue;

    const measuredItemHeight =
      Math.ceil(getThumbnailImageHeight({ width, metric, shape })) +
      labelAndGapHeight;
    const delta = measuredItemHeight - estimatedItemHeight;
    if (delta === 0) continue;

    prefixDeltaAfterPage += delta;
    prefixHeightDeltas.push({ pageNumber, prefixDeltaAfterPage });
  }

  return prefixHeightDeltas;
}

function getPrefixHeightDeltaBeforePage(
  layout: PdfThumbnailLayout,
  pageNumber: number,
) {
  let low = 0;
  let high = layout.prefixHeightDeltas.length - 1;
  let result = 0;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const delta = layout.prefixHeightDeltas[mid];

    if (delta.pageNumber < pageNumber) {
      result = delta.prefixDeltaAfterPage;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return result;
}

function normalizePageCount(pageCount: number) {
  return Number.isInteger(pageCount) && pageCount > 0 ? pageCount : 0;
}

function normalizeWidth(width: number) {
  return normalizeSize(width, 0);
}

function normalizeSize(value: number, fallback: number) {
  return Number.isFinite(value) && value > 0 ? value : fallback;
}

